package p;
import org.springframework.boot.autoconfigure.web.servlet.WebMvcRegistrations;
import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;
public class WebConfig {
    public WebMvcRegistrations registrations() {
        return new WebMvcRegistrations() {
            @Override public RequestMappingHandlerMapping getRequestMappingHandlerMapping() {
                RequestMappingHandlerMapping mapping = new RequestMappingHandlerMapping();
                mapping.setPathPrefixes(prefixes());
                return mapping;
            }
        };
    }
}

package p;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.method.HandlerTypePredicate;
import org.springframework.web.servlet.config.annotation.PathMatchConfigurer;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
public class ApiConfig implements WebMvcConfigurer {
    @Override public void configurePathMatch(PathMatchConfigurer configurer) {
        configurer
            .setUseTrailingSlashMatch(false)
            .addPathPrefix("/api", HandlerTypePredicate.forAnnotation(RestController.class));
    }
}

package p;
import org.springframework.web.reactive.config.PathMatchConfigurer;
import org.springframework.web.reactive.config.WebFluxConfigurer;
public class FluxConfig implements WebFluxConfigurer {
    @Override public void configurePathMatching(PathMatchConfigurer configurer) {
        configurer.addPathPrefix("/v1", c -> c.getPackageName().startsWith("com.acme.v1"));
        configurer.addPathPrefix("/v2", c -> c.getPackageName().startsWith("com.acme.v2"));
    }
}

package p;
public class Paths {
    private final StringBuilder sb = new StringBuilder();
    String addPrefix(String p) { return sb.append(p).toString(); }
    void setPathPrefixes(Object mapping) { addPrefix("/x"); }
}

package p;
class Storage {
    void addPathPrefix(String d) {}
    void save() { addPathPrefix("/backup"); }
}

package p;
import org.springframework.web.servlet.config.annotation.*;
public class ApiConfig implements WebMvcConfigurer {
    @Override public void configurePathMatch(PathMatchConfigurer c) {
        c.addPathPrefix("/api", t -> true);
    }
}

package p;
public class FullyQualified {
    void config(org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping mapping) {
        mapping.setPathPrefixes(null);
    }
}

package p;
import org.springframework.web.servlet.config.annotation.PathMatchConfigurer;
public class UnrelatedSetting {
    void config(PathMatchConfigurer ignored, Storage storage) {
        storage.addPathPrefix("/backup");
    }
}

package p;
import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;
public class PrefixedMapping extends RequestMappingHandlerMapping {
    public PrefixedMapping() {
        setPathPrefixes(null);
    }
}
